CREATE TABLE IF NOT EXISTS `machine_status_logs` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `machineId` int NOT NULL,
  `status` enum('online','offline') NOT NULL,
  `ipAddress` varchar(45),
  `timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `duration` int,
  `notificationSent` boolean NOT NULL DEFAULT false,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX `idx_status_logs_machine` ON `machine_status_logs` (`machineId`);
CREATE INDEX `idx_status_logs_timestamp` ON `machine_status_logs` (`timestamp`);
CREATE INDEX `idx_status_logs_status` ON `machine_status_logs` (`status`);

CREATE TABLE IF NOT EXISTS `machine_heartbeats` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `machineId` int NOT NULL,
  `ipAddress` varchar(45),
  `status` enum('running','stopped','error','maintenance') NOT NULL DEFAULT 'running',
  `cpuUsage` decimal(5,2),
  `memoryUsage` decimal(5,2),
  `diskUsage` decimal(5,2),
  `temperature` decimal(5,2),
  `timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX `idx_heartbeats_machine` ON `machine_heartbeats` (`machineId`);
CREATE INDEX `idx_heartbeats_timestamp` ON `machine_heartbeats` (`timestamp`);

